with valid_shipments as (select * from shipments where not (cost <= 64 or carrier in ('DHL', 'Kerry', 'FedEx'))), agg as (select status, date_trunc('MONTH', shipped_date) as shipped_month, count(cost) as cost_count, max(delivered_date) as last_delivered_date from valid_shipments group by status, date_trunc('MONTH', shipped_date)) select status, shipped_month, last_delivered_date from agg order by status desc, shipped_month asc limit 50;
